      17: { title: 'Recommend a Book', genre: 'recomendación cultural', readingTitle: 'The school reading club', readingText: 'The reading club is choosing a book for next month. Members like stories about real life, friendship, travel, and family. The book should not be too long because everyone has a busy schedule.', prompt: 'Recommend a book or story you know. Describe it briefly and say who would enjoy it.', model: 'I recommend The Little Prince because it is a short story about friendship and travel. I read it last year, and I liked the simple language and the interesting ideas. It is a good book for busy students who want to read something thoughtful but not difficult.', terms: [{ term: 'I recommend', kind: 'estructura' }, { term: 'because', kind: 'conector' }, { term: 'last year', kind: 'adverbio' }, { term: 'simple language', kind: 'vocabulario' }, { term: 'thoughtful', kind: 'adjetivo' }, { term: 'but not', kind: 'conector' }] },
      18: { title: 'Explain Club Rules', genre: 'normas sencillas', readingTitle: 'A new conversation club', readingText: 'The school is starting a conversation club. Members should arrive on time, speak English as much as possible, listen when another person is talking, and help new members feel welcome.', prompt: 'Write a short welcome message for a new member. Explain at least three club rules.', model: 'Welcome to the conversation club! Please arrive on time so we can start together. You should speak English as much as possible, but you can ask for help when you need it. Listen carefully when other people are talking, and be friendly to new members.', terms: [{ term: 'Please arrive', kind: 'estructura' }, { term: 'so', kind: 'conector' }, { term: 'as much as possible', kind: 'adverbio' }, { term: 'but you can', kind: 'conector' }, { term: 'Listen carefully', kind: 'estructura' }, { term: 'friendly', kind: 'adjetivo' }] },
      19: { title: 'Choose an Accommodation', genre: 'comparación práctica', readingTitle: 'Two places to stay', readingText: 'You can stay in Hotel Sun or Riverside Hostel. Hotel Sun is more comfortable and closer to the station, but it is more expensive. Riverside Hostel is cheaper and has a kitchen, although it is twenty minutes from the centre.', prompt: 'Write to a travel partner. Compare the two places and choose one with reasons.', model: 'I think we should stay at Riverside Hostel because it is cheaper and has a kitchen. Hotel Sun is more comfortable and closer to the station, but it costs too much for us. The hostel is farther from the centre, although we can take a bus. We can save money for activities.', terms: [{ term: 'I think we should', kind: 'estructura' }, { term: 'cheaper', kind: 'adjetivo' }, { term: 'but', kind: 'conector' }, { term: 'farther', kind: 'adjetivo' }, { term: 'although', kind: 'conector' }, { term: 'save money', kind: 'estructura' }] },
      20: { title: 'Share a Travel Update', genre: 'actualización de viaje', readingTitle: 'A delayed flight', readingText: 'Your flight home is delayed for three hours because of bad weather. The airline gives passengers food vouchers and says that the new departure time is 9:45 p.m. Your family is waiting for news.', prompt: 'Write a travel update to your family. Explain the delay, the new time, and how you feel.', model: 'Hi everyone! My flight is delayed for three hours because of bad weather. The airline says that we will leave at nine forty-five this evening. They gave us food vouchers, so I can have dinner here. I am tired, but everything is okay. I will message you when I arrive.', terms: [{ term: 'is delayed', kind: 'estructura' }, { term: 'because of', kind: 'conector' }, { term: 'will leave', kind: 'estructura' }, { term: 'this evening', kind: 'adverbio' }, { term: 'so', kind: 'conector' }, { term: 'everything is okay', kind: 'estructura' }] },
