function getGrammarReferences(language: WritingLanguage, level: WritingLevel, sequence: number): WritingGrammarReference[] {
  const topics = getTopicsByLevel(language, level)
  if (!topics.length) return []

  const primary = topics[(sequence - 1) % topics.length]
  return [primary].map(topic => ({
    slug: topic.slug,
    title: topic.shortTitle,
    rationale: `Práctica comunicativa del componente ${topic.shortTitle} en el nivel ${level.toUpperCase()}.`,
  }))
}

function getLegacyTask(language: WritingLanguage, level: WritingLevel, sequence: number) {
  const key = `${language}/${level}` as keyof typeof legacyBanks
  return (legacyBanks[key] as LegacyWritingTask[] | undefined)?.find(task => task.id === sequence)
}

function modelTerms(model: string, count: number, vocabulary: LegacyWritingTask['vocab'] = []): RequiredWritingTerm[] {
  const isCjkText = /[\u3040-\u30ff\u3400-\u9fff]/.test(model)
  const compactModel = model.replace(/\s+/g, '')
  const cjkTerms = vocabulary
    .map(item => typeof item === 'string' ? item : item.word)
    .map(item => item.replace(/\s*\([^)]*\)/g, '').replace(/[_＿～]/g, '').replace(/\s+/g, ''))
    .filter(item => item.length >= 2 && compactModel.includes(item))
    .filter((item, index, all) => all.indexOf(item) === index)
  const cjkModelTerms = model
    .split(/[。！？!?、，,]/)
    .map(item => item.replace(/\s+/g, '').trim())
    .filter(item => item.length >= 3)
    .map(item => item.slice(0, Math.min(item.length, 8)))
    .filter((item, index, all) => all.indexOf(item) === index)
  const spacedTerms = model
    .replace(/[.,!?;:()[\]{}"“”‘’«»]/g, ' ')
    .split(/\s+/)
    .map(term => term.trim())
    .filter(term => term.length >= 3)
    .filter((term, index, all) => all.indexOf(term) === index)
  const terms = (isCjkText && cjkTerms.length >= count
    ? cjkTerms
    : isCjkText && cjkModelTerms.length >= count
      ? cjkModelTerms
      : spacedTerms)
    .slice(0, Math.max(count + 2, 6))

  return terms.map((term, index) => ({
    term,
    kind: index === 0 ? 'estructura' : index === 1 ? 'conector' : 'vocabulario',
  }))
}

function normalizedTerm(value: string) {
  const normalized = value
    .toLocaleLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[.,!?;:()[\]{}"'“”‘’«»]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()

  return /[\u3040-\u30ff\u3400-\u9fff]/.test(normalized)
    ? normalized.replace(/\s+/g, '')
    : normalized
}

function usableTerms(terms: RequiredWritingTerm[], model: string, requiredCount: number): RequiredWritingTerm[] {
  const normalizedModel = normalizedTerm(model)
  const matchingTerms = terms.filter(term => normalizedModel.includes(normalizedTerm(term.term)))
  const fallbackTerms = modelTerms(model, requiredCount)
    .filter(term => normalizedModel.includes(normalizedTerm(term.term)))

  return [...matchingTerms, ...fallbackTerms].filter((term, index, all) =>
    all.findIndex(candidate => normalizedTerm(candidate.term) === normalizedTerm(term.term)) === index,
  )
}

export function getIntegratedWritingExercise(language: WritingLanguage, level: WritingLevel, sequence = 1): IntegratedWritingExercise {
  const profile = profiles[language]
  const levelData = profile[level]
  const rules = LEVEL_RULES[level]
  const legacyTask = getLegacyTask(language, level, sequence)
  const supplementalTask = supplementalExercises[language]?.[level]?.[sequence]
  const modelAnswer = supplementalTask?.model ?? legacyTask?.model ?? levelData.model
  const initialTerms = supplementalTask?.terms ?? (legacyTask ? modelTerms(legacyTask.model, rules.requiredCount, legacyTask.vocab) : levelData.terms)

  return {
    id: `${language}-${level}-integrated-${sequence}`,
    sequence,
    title: supplementalTask?.title ?? legacyTask?.title ?? levelData.title,
    genre: supplementalTask?.genre ?? legacyTask?.topic ?? levelData.genre,
    level,
    language,
    languageLabel: profile.label,
    languageNative: profile.native,
    backHref: `${profile.backBase}/${level}`,
    color: profile.color,
    readingTitle: supplementalTask?.readingTitle ?? (legacyTask ? `Contexto: ${legacyTask.topic}` : levelData.readingTitle),
    readingText: supplementalTask?.readingText ?? levelData.readingText,
    prompt: supplementalTask?.prompt ?? legacyTask?.prompt ?? levelData.prompt,
    minWords: rules.minWords,
    requiredCount: rules.requiredCount,
    requiredTerms: usableTerms(initialTerms, modelAnswer, rules.requiredCount),
    readingFocus: rules.readingFocus,
    planningQuestions: rules.planningQuestions,
    successCriteria: legacyTask?.criteria ?? rules.successCriteria,
    modelAnswer,
    modelNote: legacyTask ? legacyTask.checklist.join(' ') : rules.modelNote,
    cefrDescriptor: rules.cefrDescriptor,
    grammarReferences: getGrammarReferences(language, level, sequence),
  }
}

export function getIntegratedWritingExercises(language: WritingLanguage, level: WritingLevel): IntegratedWritingExercise[] {
  return Array.from({ length: 20 }, (_, index) => getIntegratedWritingExercise(language, level, index + 1))
}

export function getWritingExercisesForGrammar(language: WritingLanguage, level: WritingLevel, grammarSlug: string) {
  return getIntegratedWritingExercises(language, level).filter(exercise =>
    exercise.grammarReferences.some(reference => reference.slug === grammarSlug),
  )
}
